 };
 
+static struct zswap_pool *zswap_entry_pool(struct zswap_entry *entry)
+{
+	struct zswap_pool *pool = zswap_pool_by_index(entry->pool_idx);
+
+	VM_WARN_ON_ONCE(!pool);
